
import mongoose from "mongoose";

const { Schema } = mongoose;

const preSaveAuthorizationSchema = new Schema(
  {
    // Random identifier generated by our backend for a guest.
    // This is NOT a User ID or platform account.
    guestId: {
      type: String,
      required: true,
      index: true,
    },

    provider: {
      type: String,
      enum: [
        "spotify",
        "appleMusic",
        "deezer",
        "youtubeMusic",
        "tidal",
      ],
      required: true,
    },

    // Streaming provider's account ID, where available.
    providerUserId: {
      type: String,
      default: null,
    },

    // Encrypted tokens only. Never store raw OAuth tokens.
    accessTokenEncrypted: {
      type: String,
      required: true,
      select: false,
    },

    refreshTokenEncrypted: {
      type: String,
      default: null,
      select: false,
    },

    tokenExpiresAt: {
      type: Date,
      default: null,
    },

    scopes: {
      type: [String],
      default: [],
    },

    tokenType: {
      type: String,
      default: "Bearer",
    },

    status: {
      type: String,
      enum: [
        "active",
        "expired",
        "revoked",
        "reauthorization_required",
        "failed",
      ],
      default: "active",
      index: true,
    },

    authorizedAt: {
      type: Date,
      default: Date.now,
    },

    lastUsedAt: {
      type: Date,
      default: null,
    },

    lastRefreshedAt: {
      type: Date,
      default: null,
    },

    revokedAt: {
      type: Date,
      default: null,
    },
  },
  {
    timestamps: true,
  }
);

// A guest can connect one account per provider.
// The same authorization can be reused across campaigns.
preSaveAuthorizationSchema.index(
  {
    guestId: 1,
    provider: 1,
  },
  {
    unique: true,
  }
);

preSaveAuthorizationSchema.index({
  provider: 1,
  providerUserId: 1,
});

const PreSaveAuthorization = mongoose.model(
  "PreSaveAuthorization",
  preSaveAuthorizationSchema
);

export default PreSaveAuthorization;
